/**
 * WebSocket upgrade handler for the Drift server.
 *
 * Attaches a `ws.Server` to a Fastify HTTP server. The full protocol lives
 * in `@shared/ws-protocol` (TASK-9); for now we only echo a hello frame
 * so smoke tests can verify the upgrade end-to-end.
 */
import { WebSocketServer, type WebSocket } from "ws";
import type { FastifyInstance } from "fastify";

export interface WsHandle {
  /** Underlying `ws.Server`; exposed for tests and graceful shutdown. */
  wss: WebSocketServer;
  /** Close every active socket and stop accepting new ones. */
  close: () => Promise<void>;
}

/**
 * Attach a `ws.Server` to `app.server.httpServer` on `wsPath`.
 *
 * Returns a handle whose `close()` resolves once every socket has been
 * terminated, so the caller can `await` it during graceful shutdown.
 */
export function attachWs(app: FastifyInstance, wsPath: string): WsHandle {
  if (!app.server) {
    throw new Error("Fastify app is not listening; cannot attach WebSocket server.");
  }
  const wss = new WebSocketServer({ noServer: true });

  app.server.on("upgrade", (request, socket, head) => {
    const url = request.url ?? "";
    if (!url.startsWith(wsPath)) {
      socket.destroy();
      return;
    }
    wss.handleUpgrade(request, socket, head, (ws) => {
      wss.emit("connection", ws, request);
    });
  });

  wss.on("connection", (ws: WebSocket) => {
    ws.send(JSON.stringify({ type: "hello", t: Date.now() }));
    ws.on("error", () => {
      // Swallow per-socket errors; the server keeps running. Detailed
      // logging will land with TASK-9 (protocol + handshake).
    });
  });

  return {
    wss,
    close: () =>
      new Promise<void>((resolve) => {
        for (const client of wss.clients) {
          client.terminate();
        }
        wss.close(() => resolve());
      }),
  };
}

/**
 * Fastify application factory.
 *
 * Exposes a single `buildApp(config)` entry point so tests can `inject()`
 * requests without binding a TCP port. The full route table will grow with
 * subsequent tasks; the only handler that exists today is the `/api/health`
 * smoke check required by TASK-68.
 */
import Fastify, { type FastifyInstance } from "fastify";
import type { ServerConfig } from "./config.js";

export interface BuildAppOptions {
  /** Disable Fastify's startup logger (useful in tests). */
  quietLogger?: boolean;
}

/**
 * Construct a Fastify instance with the Drift baseline:
 *  - JSON body parser enabled (consumed by future REST handlers).
 *  - `/api/health` route returning `{ ok: true, galaxySeed }`.
 *
 * The function is intentionally side-effect free: it does NOT call
 * `app.listen()`. The entrypoint (`src/server/index.ts`) is responsible
 * for binding to a TCP port.
 */
export async function buildApp(
  config: ServerConfig,
  options: BuildAppOptions = {},
): Promise<FastifyInstance> {
  const app = Fastify({
    logger: options.quietLogger ? false : { level: process.env.LOG_LEVEL ?? "info" },
  });

  app.get("/api/health", async () => ({
    ok: true,
    galaxySeed: config.galaxySeed,
  }));

  return app;
}

/**
 * Drift server entry point.
 *
 * Reads config from `.env.local`, builds the Fastify app, attaches the
 * WebSocket server, and listens on `config.port`. `tsx watch` invokes this
 * file during `npm run dev`; production launches it via `node
 * dist/server/index.js` (TASK-69).
 *
 * Graceful shutdown closes both the HTTP server and the ws handle so the
 * process exits cleanly when killed by `tsx`/CI.
 */
import { serverConfig } from "./config.js";
import { buildApp } from "./server.js";
import { attachWs } from "./ws.js";

async function main(): Promise<void> {
  const app = await buildApp(serverConfig);
  const ws = attachWs(app, serverConfig.wsPath);

  await app.listen({ port: serverConfig.port, host: "0.0.0.0" });
  app.log.info(
    { port: serverConfig.port, wsPath: serverConfig.wsPath },
    "drift server listening",
  );

  const shutdown = async (signal: string): Promise<void> => {
    app.log.info({ signal }, "shutting down");
    try {
      await ws.close();
      await app.close();
    } finally {
      process.exit(0);
    }
  };

  process.on("SIGINT", () => void shutdown("SIGINT"));
  process.on("SIGTERM", () => void shutdown("SIGTERM"));
}

main().catch((err: unknown) => {
  // Surface the error then exit with a non-zero code so `tsx watch` respawns.
  console.error("[drift-server] fatal:", err);
  process.exit(1);
});

/**
 * Drift client entry point.
 *
 * Mounts the React DOM tree inside `#root` and renders a minimal shell
 * with a stable `<canvas>` placeholder. The three.js renderer (TASK-26)
 * will own the canvas directly; React only manages HUD/menus around it
 * per the architecture constraints in the project PRD.
 */
import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { App } from "./App.js";

const container = document.getElementById("root");
if (!container) {
  throw new Error("Missing #root container in index.html");
}

createRoot(container).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

/**
 * Top-level React shell.
 *
 * One concern: lay out the canvas placeholder (which the three.js renderer
 * will eventually adopt) and the HUD slot. Real HUD widgets land in
 * TASK-50/TASK-51/TASK-52/TASK-53; this scaffold intentionally renders
 * nothing fancier than a centered title so smoke screenshots stay clean.
 */
import { CanvasStage } from "./components/CanvasStage.js";

export function App(): JSX.Element {
  return (
    <div
      style={{
        position: "fixed",
        inset: 0,
        background: "#05060a",
        color: "#e6edf3",
        fontFamily: "system-ui, sans-serif",
      }}
    >
      <CanvasStage />
      <header
        style={{
          position: "absolute",
          top: 16,
          left: 16,
          padding: "8px 12px",
          background: "rgba(0, 0, 0, 0.4)",
          borderRadius: 6,
          letterSpacing: "0.18em",
          fontSize: 12,
          textTransform: "uppercase",
        }}
      >
        Drift — scaffold
      </header>
    </div>
  );
}

/**
 * Stable `<canvas>` placeholder.
 *
 * Three.js will mount into this element once TASK-26 (streaming pipeline)
 * lands. Until then it sits empty so the page has the correct layout and
 * Playwright smoke tests can assert the canvas is present.
 */
export function CanvasStage(): JSX.Element {
  return (
    <canvas
      id="drift-canvas"
      data-testid="drift-canvas"
      style={{ display: "block", width: "100vw", height: "100vh" }}
    />
  );
}

/**
 * Shared health-check payload.
 *
 * Used by both the Fastify handler in `src/server` and the client-side
 * status indicators in `src/client`. Living in `src/shared` keeps the
 * wire shape in one place so server and client never drift.
 */
export interface HealthPayload {
  ok: boolean;
  galaxySeed: string;
}

/** Default payload used when no server config is available (tests, SSR). */
export const FALLBACK_HEALTH: HealthPayload = {
  ok: true,
  galaxySeed: "DRIFT-SEED-0001",
};

/** Pure constructor so tests can build snapshots without side effects. */
export function makeHealth(galaxySeed: string): HealthPayload {
  return { ok: true, galaxySeed };
}

import { describe, it, expect } from "vitest";
import { makeHealth, FALLBACK_HEALTH, type HealthPayload } from "./health.js";

describe("shared/health", () => {
  it("builds a payload with ok=true and the supplied seed", () => {
    const payload: HealthPayload = makeHealth("TEST-SEED");
    expect(payload.ok).toBe(true);
    expect(payload.galaxySeed).toBe("TEST-SEED");
  });

  it("exposes a fallback with the default seed", () => {
    expect(FALLBACK_HEALTH.ok).toBe(true);
    expect(FALLBACK_HEALTH.galaxySeed).toMatch(/^DRIFT-SEED-/);
  });
});

/**
 * Server smoke tests.
 *
 * Boots a Fastify app via `buildApp()` and exercises the `/api/health`
 * endpoint with `inject()`. No TCP port is bound; the test stays fast and
 * isolated from any other process that might be using `PORT`.
 */
import { describe, it, expect, beforeAll, afterAll } from "vitest";
import type { FastifyInstance } from "fastify";
import { buildApp } from "./server.js";
import { loadConfig } from "./config.js";
import type { HealthPayload } from "@shared/health.js";

describe("server /api/health", () => {
  let app: FastifyInstance;

  beforeAll(async () => {
    const config = loadConfig();
    app = await buildApp(config, { quietLogger: true });
    await app.ready();
  });

  afterAll(async () => {
    await app.close();
  });

  it("returns 200 with ok=true and a galaxySeed", async () => {
    const response = await app.inject({ method: "GET", url: "/api/health" });
    expect(response.statusCode).toBe(200);
    const body = response.json() as HealthPayload;
    expect(body.ok).toBe(true);
    expect(typeof body.galaxySeed).toBe("string");
    expect(body.galaxySeed.length).toBeGreaterThan(0);
  });
});

